test('buildUrl queryOrder defaults to sorted keys', () => {
  const base = { baseUrl: 'https://a.test', query: { b: 1, a: 2 } };
  assert.equal(buildUrl(base), 'https://a.test/?a=2&b=1');
  assert.equal(buildUrl({ ...base, queryOrder: 'sorted' }), 'https://a.test/?a=2&b=1');
});

test('buildUrl queryOrder insertion keeps key order and array order', () => {
  const url = buildUrl({
    baseUrl: 'https://a.test',
    query: { b: [3, 1, 2], a: 'x' },
    queryOrder: 'insertion'
  });
  assert.equal(url, 'https://a.test/?b=3&b=1&b=2&a=x');
});

test('buildUrl sorted keeps array order', () => {
  const url = buildUrl({ baseUrl: 'https://a.test', query: { b: [3, 1], a: 'x' } });
  assert.equal(url, 'https://a.test/?a=x&b=3&b=1');
});

test('buildUrl rejects unknown queryOrder', () => {
  for (const queryOrder of ['random', null, 1, '']) {
    assert.throws(() => buildUrl({ baseUrl: 'https://a.test', queryOrder }), TypeError);
  }
});

test('buildUrl passes URLSearchParams through regardless of queryOrder', () => {
  const query = new URLSearchParams('b=1&a=2');
  for (const queryOrder of ['sorted', 'insertion']) {
    assert.equal(buildUrl({ baseUrl: 'https://a.test', query, queryOrder }), 'https://a.test/?b=1&a=2');
  }
});

test('buildSignedUrl forwards queryOrder', () => {
  const url = buildSignedUrl({ baseUrl: 'https://a.test', query: { b: 1, a: 2 }, queryOrder: 'insertion' }, 'k');
  assert.ok(url.startsWith('https://a.test/?b=1&a=2&signature='));
  assert.throws(() => buildSignedUrl({ baseUrl: 'https://a.test', queryOrder: 'x' }, 'k'), TypeError);
});
